record.field:
stock_quant_obj = env['stock.quant']
for connection in records.producteca_connection_ids:
    stock_quant_obj.with_delay().sync_product_stock_to_producteca(connection.id)

templates_to_clean = records.with_context(active_test=False).filtered(
    lambda template: not template.is_producteca_product and template.producteca_connection_ids
)
connections = templates_to_clean.with_context(active_test=False).mapped('producteca_connection_ids')
if connections:
    connections.sudo().unlink()
